using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

var path = "/home/runner/.nuget/packages/xunit.v3.extensibility.core/1.0.0/lib/netstandard2.0/xunit.v3.core.dll";
using var stream = File.OpenRead(path);
using var pe = new PEReader(stream);
var mr = pe.GetMetadataReader();

foreach(var tdh in mr.TypeDefinitions) {
    var td = mr.GetTypeDefinition(tdh);
    var name = mr.GetString(td.Name);
    if (name != "ITestCaseOrderer") continue;
    var ns = mr.GetString(td.Namespace);
    Console.WriteLine($"Found: {ns}.{name}");
    foreach(var mh in td.GetMethods()) {
        var md = mr.GetMethodDefinition(mh);
        var mname = mr.GetString(md.Name);
        Console.WriteLine($"  Method: {mname}");
        var sig = md.DecodeSignature(new SignatureTypeProvider(), null);
        Console.WriteLine($"  GenericParamCount: {sig.GenericParameterCount}");
    }
    // Check generic params
    foreach(var gph in td.GetGenericParameters()) {
        var gp = mr.GetGenericParameter(gph);
        Console.WriteLine($"  TypeGenericParam: {mr.GetString(gp.Name)} attrs={gp.Attributes}");
        foreach(var gc in gp.GetConstraints()) {
            var c = mr.GetGenericParameterConstraint(gc);
            Console.WriteLine($"    Constraint: {c.Type}");
        }
    }
}

class SignatureTypeProvider : ISignatureTypeProvider<string, object?> {
    public string GetPrimitiveType(PrimitiveTypeCode typeCode) => typeCode.ToString();
    public string GetTypeFromDefinition(MetadataReader reader, TypeDefinitionHandle handle, byte rawTypeKind) => "typedef";
    public string GetTypeFromReference(MetadataReader reader, TypeReferenceHandle handle, byte rawTypeKind) => "typeref";
    public string GetTypeFromSpecification(MetadataReader reader, object? genericContext, TypeSpecificationHandle handle, byte rawTypeKind) => "typespec";
    public string GetSZArrayType(string elementType) => elementType + "[]";
    public string GetPointerType(string elementType) => elementType + "*";
    public string GetByReferenceType(string elementType) => "ref " + elementType;
    public string GetPinnedType(string elementType) => elementType;
    public string GetGenericInstantiation(string genericType, System.Collections.Immutable.ImmutableArray<string> typeArguments) => genericType;
    public string GetArrayType(string elementType, ArrayShape shape) => elementType + "[*]";
    public string GetModifiedType(string modifier, string unmodifiedType, bool isRequired) => unmodifiedType;
    public string GetFunctionPointerType(MethodSignature<string> signature) => "fnptr";
    public string GetGenericMethodParameter(object? genericContext, int index) => $"!!{index}";
    public string GetGenericTypeParameter(object? genericContext, int index) => $"!{index}";
}
